using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;
namespace RebirthEntityStudio {
 public enum TorsoWoundInterior {None=0,Ribs=1,Bowel=2}
 [Serializable]public sealed class BodyDeepWound {
  public Color tissueTint=Color.white,boneTint=Color.white;public float tissueSmoothness=.3f,boneSmoothness=.3f,tissueTileSize=.035f;
  public Vector2 uv;public Vector3 referencePoint,referenceNormal;public float width=.044f,height=.11f,depth=.027f,rotation;public bool exposeBone;
  public TorsoWoundInterior torsoInterior;
  public float bloodCoverage,boneBloodCoverage;
  static Color Tint(Color c){foreach(float v in new[]{c.r,c.g,c.b})if(float.IsNaN(v)||float.IsInfinity(v))throw new InvalidDataException("Invalid wound colour");return new Color(Mathf.Clamp01(c.r),Mathf.Clamp01(c.g),Mathf.Clamp01(c.b),1);}
  public void Validate(){if(!Enum.IsDefined(typeof(TorsoWoundInterior),torsoInterior)||(torsoInterior!=TorsoWoundInterior.None&&exposeBone))throw new InvalidDataException("Choose either a torso interior or shin bone exposure");tissueTint=Tint(tissueTint);boneTint=Tint(boneTint);foreach(float v in new[]{tissueSmoothness,boneSmoothness,tissueTileSize,bloodCoverage,boneBloodCoverage})if(float.IsNaN(v)||float.IsInfinity(v))throw new InvalidDataException("Invalid wound material setting");bloodCoverage=Mathf.Clamp01(bloodCoverage);boneBloodCoverage=Mathf.Clamp01(boneBloodCoverage);tissueSmoothness=Mathf.Clamp01(tissueSmoothness);boneSmoothness=Mathf.Clamp01(boneSmoothness);tissueTileSize=Mathf.Clamp(tissueTileSize,.005f,.2f);foreach(float v in new[]{uv.x,uv.y,referencePoint.x,referencePoint.y,referencePoint.z,referenceNormal.x,referenceNormal.y,referenceNormal.z,width,height,depth,rotation})if(float.IsNaN(v)||float.IsInfinity(v))throw new InvalidDataException("Invalid deep wound setting");if(referenceNormal.sqrMagnitude<.1f||uv.x<0||uv.x>1||uv.y<0||uv.y>1)throw new InvalidDataException("Invalid deep wound surface anchor");bool torso=torsoInterior!=TorsoWoundInterior.None;width=Mathf.Clamp(width,.008f,torso?.3f:.12f);height=Mathf.Clamp(height,.012f,torso?.4f:.24f);depth=Mathf.Clamp(depth,.002f,torso?.12f:.05f);rotation=Mathf.Repeat(rotation+180,360)-180;}
 }
 [Serializable]public sealed class BodyWoundLibrary {public int version;public string fieldFile,fleshFile,boneFile;public BodyWoundFile[] files;}
 [Serializable]public sealed class BodyWoundFile {public string name,sha256;}
 [Serializable]public sealed class BodyWoundField {public int version,width,height;public float[] distances;}
 [Serializable]public sealed class BodyWoundBoneLibrary {public int version;public string license,attribution,licenseUrl,sourceArchiveUrl,sourceArchiveSha256,foundationHash;public float referenceHeight,posteriorOffset,minimumShankFraction,maximumShankFraction;public BodyWoundBone[] bones;}
 [Serializable]public sealed class BodyWoundBone {public string side,fma,sourceSha256;public float[] positions,sourceAnkle,sourceKnee,sourceRight,sourceUp,sourceForward;public int[] triangles;public float referenceTransverseScale;}
 public sealed class BodyWoundResources {
  public string path,folder;public BodyWoundLibrary definition;public BodyWoundField field;public BodyWoundBoneLibrary bone;public Texture2D flesh;
  public string Child(string name){if(string.IsNullOrEmpty(name)||Path.GetFileName(name)!=name)throw new InvalidDataException("Invalid wound library filename");return folder+"/"+name;}
  public static BodyWoundResources Read(string guid){string path=string.IsNullOrEmpty(guid)?AssetDatabase.FindAssets("WoundLibrary_v1 t:TextAsset").Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault(p=>p.EndsWith("/BodyGeneratorData/WoundLibrary_v1.json",StringComparison.Ordinal)):AssetDatabase.GUIDToAssetPath(guid);if(string.IsNullOrEmpty(path)||!File.Exists(path))throw new FileNotFoundException("Install the deep wound library");var r=new BodyWoundResources{path=path,folder=Path.GetDirectoryName(path).Replace('\\','/')};r.definition=JsonUtility.FromJson<BodyWoundLibrary>(File.ReadAllText(path));if(r.definition==null||r.definition.version!=1||r.definition.files==null)throw new InvalidDataException("Invalid deep wound library");foreach(var file in r.definition.files){string child=r.Child(file.name);using(var sha=System.Security.Cryptography.SHA256.Create()){if(!File.Exists(child)||BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(child))).Replace("-","").ToLowerInvariant()!=file.sha256)throw new InvalidDataException("Deep wound source changed: "+file.name);}}
   foreach(string name in new[]{r.definition.fieldFile,r.definition.fleshFile,r.definition.boneFile})if(!r.definition.files.Any(f=>f.name==name))throw new InvalidDataException("Missing declared wound source");r.field=JsonUtility.FromJson<BodyWoundField>(File.ReadAllText(r.Child(r.definition.fieldFile)));if(r.field==null||r.field.version!=1||r.field.width<8||r.field.width>1024||r.field.height<8||r.field.height>1024||r.field.distances==null||r.field.distances.Length!=r.field.width*r.field.height||r.field.distances.Any(v=>float.IsNaN(v)||float.IsInfinity(v)))throw new InvalidDataException("Invalid wound opening field");r.bone=JsonUtility.FromJson<BodyWoundBoneLibrary>(File.ReadAllText(r.Child(r.definition.boneFile)));r.flesh=AssetDatabase.LoadAssetAtPath<Texture2D>(r.Child(r.definition.fleshFile));if(r.flesh==null)throw new FileNotFoundException("Wound flesh texture missing");return r;}
  public Texture2D CreateField(){var result=new Texture2D(field.width,field.height,TextureFormat.RFloat,false,true){name="Deep wound signed distance",wrapMode=TextureWrapMode.Clamp,filterMode=FilterMode.Bilinear,hideFlags=HideFlags.HideAndDontSave};result.SetPixelData(field.distances,0);result.Apply();return result;}
  public string Export(string folder){string target=folder+"/DeepWoundLibrary";AssetDatabase.CreateFolder(folder,"DeepWoundLibrary");foreach(var file in definition.files)if(!AssetDatabase.CopyAsset(Child(file.name),target+"/"+file.name))throw new IOException("Could not export wound source "+file.name);string manifest=target+"/WoundLibrary_v1.json";if(!AssetDatabase.CopyAsset(path,manifest))throw new IOException("Could not export wound library");return AssetDatabase.AssetPathToGUID(manifest);}
 }
}
